  "hypotheses": [
    {
      "service": "worker",
      "kind": "resource_exhaustion",
      "mechanism": "Worker service is holding 36/50 database connections, exhausting the connection pool and causing database access delays",
      "supporting": ["E4", "E15"],
      "refuting": ["E7"],
      "explains": ["I4_workflow_progress", "M4_db_pool_pressure"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "worker"}}
      ]
    },
    {
      "service": "payment-service",
      "kind": "runtime_fault",
      "mechanism": "Payment service process is stuck in a bad state causing duplicate payment attempts despite no recent deploy",
      "supporting": ["E2"],
      "refuting": ["E5", "E14"],
      "explains": ["I5_single_payment"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "payment-service"}},
        {"action": "refund_duplicate_payments", "params": {}}
      ]
    }
  ],
  "summary": "Worker database connection exhaustion causing approval delays, and payment-service runtime fault causing duplicate payments"
}
